    cands = [Path(os.environ['SOKORADAR_RAW'])] if os.environ.get('SOKORADAR_RAW') else []
    cands += [HERE / 'raw', Path.cwd() / 'raw', HERE, Path.cwd(), HERE / 'sokoradar_pipeline' / 'raw', Path.cwd() / 'sokoradar_pipeline' / 'raw']
    for c in cands:
        if all((c / f).exists() for f in RAW_FILES):
            return c
    target = HERE / 'sokoradar_raw_data'
    try:
        target.mkdir(exist_ok=True)
    except OSError:
        target = Path.cwd() / 'sokoradar_raw_data'; target.mkdir(exist_ok=True)
    if not all((target / f).exists() for f in RAW_FILES):
        print(f'No raw/ folder found - unpacking the raw data embedded in this script to {target}')
        blob = base64.b64decode(''.join(EMBEDDED_RAW_DATA.split()))
