def log(dataset, commodity, where, date, value, ref, rule, action):
    CLEAN_LOG.append((dataset, commodity, where, pd.Timestamp(date), value, ref, rule, action))
def norm(s): return re.sub(r'[^a-z]', '', str(s).lower())
def km(a1, o1, a2, o2):
    p1, p2 = math.radians(a1), math.radians(a2)
    return 2 * 6371 * math.asin(math.sqrt(math.sin((p2 - p1) / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(math.radians(o2 - o1) / 2) ** 2))

