def load_moa_daily(path):
    """MoA 'DailyUnitPrices' sheet: row 1 categories, row 2 commodity names, row 3 units, data from row 5."""
    wb = openpyxl.load_workbook(path, read_only=True, data_only=True)
    rows = list(wb['DailyUnitPrices'].iter_rows(values_only=True))
    CATS = {'CEREAL': 'Cereals', 'LEGUMES': 'Legumes', 'ROOTS & TUBERS': 'Roots & tubers', 'HORTICULTURE': 'Horticulture', 'OTHERS': 'Others'}
    cols, cur = [], None
    for c in range(2, 48):
        g, name, unit = rows[0][c], rows[1][c], rows[2][c]
        if isinstance(g, str) and g.strip().upper() in CATS: cur = CATS[g.strip().upper()]
        if name and name != 'Index': cols.append((c, cur, name.strip(), unit))
    data = [r for r in rows[4:] if r[0] is not None]
    df = pd.DataFrame({name: pd.to_numeric(pd.Series([r[c] for r in data]), errors='coerce') for c, _, name, _ in cols})
    df.index = pd.to_datetime([r[0] for r in data])
    return df, pd.DataFrame(cols, columns=['col', 'category', 'commodity', 'unit'])

def load_counties():
    c = pd.read_csv(F_COUNTIES)
    names = {norm(n): n for n in c.county}
    alias = {'emarakwet': 'Elgeyo-Marakwet', 'ijara': 'Garissa', 'merunorth': 'Meru', 'merusouth': 'Tharaka-Nithi', 'moyale': 'Marsabit'}
    names.update(alias)
    return c, names

def load_bulletin(path, cmap):
    """MoA bulletin .docx: tables are embedded Excel files. Returns national monthly series and county prices."""
    z = zipfile.ZipFile(path)
    def wbk(name): return openpyxl.load_workbook(io.BytesIO(z.read('word/embeddings/' + name)), data_only=True)
    MN = {m: i for i, m in enumerate(['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'], start=1)}
    def mnum(x):
        if isinstance(x, datetime.datetime): return x.month
        s = str(x).strip().lower()
        return next((v for k, v in MN.items() if s.startswith(k)), None)
    def num(v):
        if isinstance(v, (int, float)): return float(v)
        try: return float(str(v).replace(',', '').strip())
        except ValueError: return np.nan
    def year_grid(file, sheet, month_col, first_year_col, n_years, year0, rows):
        g = [list(r) for r in wbk(file)[sheet].iter_rows(values_only=True)]
        out = {}
        for r in range(rows[0], rows[1] + 1):
            row = g[r - 1]; m = mnum(row[month_col])
            if not m: continue
            for k in range(n_years):
                v = num(row[first_year_col + k]) if first_year_col + k < len(row) else np.nan
                if pd.notna(v): out[pd.Timestamp(year0 + k, m, 1)] = v
        return pd.Series(out).sort_index()
    national = pd.DataFrame({
        'Maize': year_grid('Microsoft_Excel_Worksheet.xlsx', 'average monthly maize national', 1, 2, 7, 2020, (3, 14)),
        'Beans': year_grid('Microsoft_Excel_Worksheet3.xlsx', 'Sheet1', 3, 4, 7, 2020, (4, 15)),
        'Irish potatoes': year_grid('Microsoft_Excel_Worksheet5.xlsx', 'Sheet1', 5, 6, 7, 2020, (26, 37))})
    rec = []
    def county_of(s): return cmap.get(norm(s)) if isinstance(s, str) else None
    months = list(pd.date_range('2025-03-01', '2026-08-01', freq='MS'))
    for sheet, name_col, first_col, crop in (('MAIZE by county', 1, 2, 'Maize'), ('BEANS by county', 0, 1, 'Beans')):
        for row in wbk('Microsoft_Excel_Worksheet1.xlsx')[sheet].iter_rows(values_only=True):
            c = county_of(row[name_col])
            if not c: continue
            for k, m in enumerate(months):
                v = num(row[first_col + k]) if first_col + k < len(row) else np.nan
                if pd.notna(v) and v > 0: rec.append((m, c, crop, 'Wholesale', v, 0))
    T1 = [('Maize', 3, 1), ('Beans', 7, 1), ('Sorghum', 14, 90), ('Wheat', 20, 90)]     # wholesale columns; bags of 90 kg
    for row in list(wbk('Microsoft_Excel_Worksheet1.xlsx')['Table 1 Monthly prices'].iter_rows(values_only=True))[1:]:
        c, m = county_of(row[0]), mnum(row[1])
        if not c or not m: continue
        for crop, col, div in T1:
            v = num(row[col]) if col < len(row) else np.nan
            if pd.notna(v) and v > 0: rec.append((pd.Timestamp(2026, m, 1), c, crop, 'Wholesale', v / div, 1))
    cp = pd.DataFrame(rec, columns=['month', 'county', 'crop', 'level', 'kes_per_kg', 'pri'])
    cp = cp.sort_values('pri').groupby(['month', 'county', 'crop', 'level'], as_index=False).kes_per_kg.first()
    return national, cp

def load_wfp(cmap):
    w = pd.read_csv(F_WFP, skiprows=[1], low_memory=False)          # row 2 is an HXL tag row
    w['date'] = pd.to_datetime(w.date); w['month'] = w.date.dt.to_period('M').dt.to_timestamp()
    w['price'] = pd.to_numeric(w.price, errors='coerce')
    w.loc[w.market.eq('Hola (Tana River)') & w.admin2.isna(), 'admin2'] = 'Tana River'   # one market is missing its admin names
    w['county'] = w.admin2.map(lambda s: cmap.get(norm(s)) if isinstance(s, str) else None)
    w['p'] = w.price / w.unit.map(UNIT_DIV)                          # per kg / per litre / per loaf
    return w[w.p.gt(0)].copy()

# =====================================================================================================================
# 2. CLEAN OUTLIERS
# =====================================================================================================================
def clean_moa_daily(raw):
    clean = raw.copy()
    for c in clean.columns:
        s = clean[c]
        for t in s[s == 0].index: log('MoA daily', c, 'National', t, 0.0, None, 'Price recorded as 0', 'Removed (missing)')
        clean.loc[s == 0, c] = np.nan
        s = clean[c].dropna()
        med = s.rolling(21, center=True, min_periods=5).median()
        bad = s[(s / med > 3) | (s / med < 1 / 3)]
        for t, v in bad.items(): log('MoA daily', c, 'National', t, float(v), float(med[t]), '>3x or <1/3 of 21-day median', 'Removed')
        clean.loc[bad.index, c] = np.nan
    if pd.Timestamp('2025-02-03') in clean.index:                   # last row is January 2025 data (confirmed by the team)
        clean = clean.rename(index={pd.Timestamp('2025-02-03'): pd.Timestamp('2025-01-31')})
    return clean.drop(index=clean.index[clean.notna().sum(axis=1) == 0])

def clean_wfp(w):
    w = w.sort_values(['market', 'commodity', 'pricetype', 'month']).copy()
    # rule 1: same market, same commodity - more than 3x (or under 1/3 of) the rolling median of 5 reports
    med = w.groupby(['market', 'commodity', 'pricetype']).p.transform(lambda s: s.rolling(5, center=True, min_periods=3).median())
    r = w.p / med
    bad = w[(r > 3) | (r < 1 / 3)]
    for row in bad.itertuples():
        log('WFP', row.commodity, f'{row.market} ({row.pricetype})', row.month, float(row.p), float(med[row.Index]), '>3x or <1/3 of 5-report market median', 'Removed')
    w = w.drop(index=bad.index)
    # rule 2: all markets, 5-month window - more than 4x (or under 1/4 of) the median of all reports in the 5 months around it
    refs = []
    for (c, t), d in w.groupby(['commodity', 'pricetype']):
        months = pd.date_range(d.month.min(), d.month.max(), freq='MS')
        by_m = d.groupby('month').p.apply(list).reindex(months)
        for i, m in enumerate(months):
            pool = [v for lst in by_m.iloc[max(0, i - 2): i + 3] if isinstance(lst, list) for v in lst]
            refs.append((c, t, m, float(np.median(pool)) if len(pool) >= 3 else np.nan))
    ref = pd.DataFrame(refs, columns=['commodity', 'pricetype', 'month', 'ref'])
    w = w.merge(ref, on=['commodity', 'pricetype', 'month'], how='left').set_index(w.index)
    r = w.p / w.ref
    bad = w[(r > 4) | (r < 1 / 4)]
    for row in bad.itertuples():
        log('WFP', row.commodity, f'{row.market} ({row.pricetype})', row.month, float(row.p), float(row.ref), '>4x or <1/4 of median of all markets (5-month window)', 'Removed')
    w = w.drop(columns='ref')
    return w.drop(index=bad.index)

# =====================================================================================================================
# 3. MISSING VALUES: MoA monthly series 2019 - Jan 2025
# =====================================================================================================================
def moa_monthly(clean, cat_of, bul_nat):
    per = clean.index.to_period('M').to_timestamp()
    obs = clean.groupby(per).mean().reindex(MOA_MONTHS)
    days = clean.groupby(per).count().reindex(MOA_MONTHS).fillna(0).astype(int)
    flag = pd.DataFrame(np.where(days >= 10, 'Observed', np.where(days >= 1, 'Thin (1-9 days, averaged)', 'Filled')), index=MOA_MONTHS, columns=obs.columns)
    dlog = np.log(obs).diff().clip(-0.4, 0.4)
    growth = pd.DataFrame(index=range(1, 13), columns=obs.columns, dtype=float)
    for c in obs.columns:
        for m in range(1, 13):
            x = dlog[c][dlog.index.month == m].dropna()
            if len(x) >= 2: growth.loc[m, c] = x.mean()
        peers = [p for p in obs.columns if cat_of[p] == cat_of[c]]
        for m in range(1, 13):
            if pd.isna(growth.loc[m, c]):
                x = dlog.loc[dlog.index.month == m, peers].stack().dropna()
                growth.loc[m, c] = x.mean() if len(x) >= 2 else 0.0
    BUL = {'Dry Maize': 'Maize', 'Red Irish Potatoes': 'Irish potatoes', 'White Irish Potatoes': 'Irish potatoes', **{b: 'Beans' for b in BEANS5}}
    filled, flag2 = obs.copy(), flag.copy()
    idx = list(MOA_MONTHS)
    for c in obs.columns:
        s = obs[c]; have = [i for i, m in enumerate(idx) if pd.notna(s[m])]
        if not have: continue
        b = bul_nat[BUL[c]] if c in BUL else None
        used = set()
        def g(i):
            if b is not None and idx[i] in b.index and idx[i - 1] in b.index and pd.notna(b[idx[i]]) and pd.notna(b[idx[i - 1]]):
                used.add(idx[i]); return float(np.log(b[idx[i]] / b[idx[i - 1]]))
            return growth.loc[idx[i].month, c]
        for a, z in zip(have[:-1], have[1:]):                         # interior gaps: growth path nudged to the next real price
            if z - a <= 1: continue
            path = [np.log(s[idx[a]])]
            for i in range(a + 1, z + 1): path.append(path[-1] + g(i))
            corr = (np.log(s[idx[z]]) - path[-1]) / (z - a)
            for k, i in enumerate(range(a + 1, z), start=1):
                filled.loc[idx[i], c] = np.exp(path[k] + corr * k)
                flag2.loc[idx[i], c] = 'Filled (MoA bulletin trend)' if idx[i] in used else 'Filled (seasonal growth)'
        v = np.log(s[idx[have[-1]]])
        for i in range(have[-1] + 1, len(idx)):
            v += g(i); filled.loc[idx[i], c] = np.exp(v); flag2.loc[idx[i], c] = 'Filled (extrapolated)'
        v = np.log(s[idx[have[0]]])
        for i in range(have[0] - 1, -1, -1):
            v -= g(i + 1); filled.loc[idx[i], c] = np.exp(v); flag2.loc[idx[i], c] = 'Filled (back-cast)'
    return obs, days, filled, flag2

# =====================================================================================================================
# 4. NATIONAL SERIES 2006 - 2024 (one reference price per commodity)
# =====================================================================================================================
def wfp_median(w, items, ptype, markets=None, start=None):
    d = w[w.commodity.isin(items) & (w.pricetype == ptype)]
    if markets is not None: d = d[d.market.isin(markets)]
    if start is not None: d = d[d.month >= start]
    return d.groupby(['month', 'market']).p.median().groupby('month').median()

def wfp_panel(w, items, ptype, start):
    d = w[w.commodity.isin(items) & (w.pricetype == ptype) & (w.month >= start) & (w.month <= END)]
    return d.groupby(['month', 'market']).p.median().unstack()

def chain(panel, level, anchor, guide):
    """Chain-link across a changing set of markets: median log change among markets reporting in both months.
    Where two reported months share < 2 markets, carry the level with the guide series' change."""
    months = [m for m in panel.index if panel.loc[m].notna().sum() >= 2 and m > anchor]
    lv = {anchor: np.log(level)}; prev = anchor
    for m in months:
        both = panel.reindex([prev, m]).dropna(axis=1)
        lv[m] = lv[prev] + (float(np.median(np.log(both.loc[m]) - np.log(both.loc[prev]))) if both.shape[1] >= 2
                            else float(np.log(guide[m] / guide[prev])))
        prev = m
    return np.exp(pd.Series(lv).sort_index())

def market_index(panel, n_iter=50):
    """Fixed-effects price index for a changing set of markets (median polish on log prices):
    log price(market, month) = market level + month level. Robust to markets entering/leaving; does not drift.
    Returned level = month level + median market level (a typical market)."""
    lp = np.log(panel)
    mkt = pd.Series(0.0, index=lp.columns)
    for _ in range(n_iter):
        mon = lp.sub(mkt, axis=1).median(axis=1)
        mkt = lp.sub(mon, axis=0).median(axis=0)
        mkt -= mkt.median()
    return np.exp(mon.dropna())

def bridge(s, idx, guide=None):
    """Fill interior gaps log-linearly, or along a guide series (its ratio interpolated). Returns (series, filled_mask)."""
    s = s.reindex(idx)
    if guide is not None:
        r = np.log(s) - np.log(guide.reindex(idx)); out = np.exp(r.interpolate(limit_area='inside') + np.log(guide.reindex(idx)))
    else:
        out = np.exp(np.log(s).interpolate(limit_area='inside'))
    return out, s.isna() & out.notna()

def growth_cast(s, driver, direction='back'):
    """Extend s beyond its first (or last) value using the month-on-month growth of a driver series."""
    s = s.reindex(ALL).copy(); dl = np.log(driver.reindex(ALL)).diff()
    known = s.dropna().index
    if direction == 'back':
        for t in reversed(ALL[ALL < known.min()]):
            s[t] = s[t + pd.DateOffset(months=1)] / np.exp(dl[t + pd.DateOffset(months=1)])
    else:
        for t in ALL[ALL > known.max()]:
            s[t] = s[t - pd.DateOffset(months=1)] * np.exp(dl[t])
    return s

def national_series(w, filled, flag2, moa_flag, nat):
    NAT, NFLAG, NOTE = {}, {}, {}
    cpi = nat['CPI index (Feb 2019=100, chained)']; fx = nat['KES per USD']
    moa_good = None
    # 4a. nine MoA commodities: WFP wholesale 2006-2018 scaled to the MoA level, MoA filled series 2019-2024
    WFPMAP = {'Dry Maize': ['Maize', 'Maize (white)'], 'Sorghum': ['Sorghum'], 'Red Irish Potatoes': ['Potatoes (Irish)'], 'White Irish Potatoes': ['Potatoes (Irish)'],
              **{b: ['Beans', 'Beans (dry)'] for b in BEANS5}}
    SCALE = {}
    for c in NINE:
        comp = wfp_median(w, WFPMAP[c], 'Wholesale', markets=OLD6)
        moa_obs = filled[c].where(moa_flag[c] == 'Observed')
        x = pd.concat([moa_obs, comp], axis=1, sort=True).dropna()
        SCALE[c] = (float((x.iloc[:, 0] / x.iloc[:, 1]).median()), len(x))
        early, gap = bridge(comp.reindex(H18) * SCALE[c][0], H18)
        NAT[c] = pd.concat([early, filled[c].reindex(ALL[ALL >= '2019-01-01'])])
        NFLAG[c] = pd.concat([pd.Series(np.where(gap, 'Interpolated', 'WFP wholesale scaled to MoA'), index=H18), flag2[c].reindex(ALL[ALL >= '2019-01-01'])])
    # 4b. wheat flour (WFP retail from Dec 2018, fixed-effects index across changing markets) - also the trend for wheat grain after MoA stops
    pnl = wfp_panel(w, ['Wheat flour'], 'Retail', '2018-12-01'); a0 = pnl.index.min()
    flour, fgap = bridge(market_index(pnl), ALL)
    # 4c. wheat and eggs: MoA from 2019; MoA wheat stops after Jan 2024 -> carried with the wheat flour trend; back-cast 2006-2018
    world_wheat_kes = (nat['Global wheat (USD/t)'] * fx / 1000)                # KES per kg, to Jun 2017
    wheat_driver = world_wheat_kes.copy()
    after = wheat_driver.last_valid_index()
    wheat_driver[ALL > after] = (wheat_driver[after] * cpi / cpi[after])[ALL > after]   # Jul 2017 - Dec 2018: CPI growth
    wheat = filled['Wheat'].reindex(ALL).where(ALL >= '2019-01-01'); wflag = flag2['Wheat'].reindex(ALL).fillna('')
    tail = [t for t in ALL if wflag[t] == 'Filled (extrapolated)']
    for t in tail:
        prev = t - pd.DateOffset(months=1); wheat[t] = wheat[prev] * flour[t] / flour[prev]; wflag[t] = 'Filled (wheat flour price trend)'
    for c, s, fl, drv, note in (('Wheat', wheat, wflag, wheat_driver, 'world wheat price in KES (IMF x CBK rate) to Jun 2017, CPI after'),
                                ('Eggs', filled['Eggs'].reindex(ALL).where(ALL >= '2019-01-01'), flag2['Eggs'].reindex(ALL).fillna(''), cpi, 'CPI')):
        NAT[c] = growth_cast(s, drv, 'back')
        NFLAG[c] = pd.Series(np.where(ALL < '2019-01-01', 'Back-cast: ' + note, fl), index=ALL)
    NAT['Wheat flour'] = growth_cast(flour, NAT['Wheat'], 'back')
    NFLAG['Wheat flour'] = pd.Series(np.where(ALL < a0, 'Back-cast: wheat grain price', np.where(fgap, 'Interpolated', 'WFP markets, fixed-effects index')), index=ALL)
    # 4d. retail WFP-based series
    milk_nbo = w[(w.commodity == 'Milk (cow, pasteurized)') & (w.market == 'Nairobi') & (w.pricetype == 'Retail')].groupby('month').p.median()
    m20 = milk_nbo.reindex(pd.date_range('2006-01-01', '2020-12-01', freq='MS'))
    uht = chain(wfp_panel(w, ['Milk (UHT)'], 'Retail', '2020-10-01'), float(m20.loc['2020-09-01':].median()), pd.Timestamp('2020-12-01'), cpi)
    milk = pd.concat([m20, uht.loc['2021-01-01':'2023-12-01']])
    past = chain(wfp_panel(w, ['Milk (cow, pasteurized)'], 'Retail', '2023-12-01'), float(milk.dropna().iloc[-1]), milk.dropna().index[-1], cpi)
    milk = pd.concat([milk, past.loc['2024-01-01':]]); milk = milk[~milk.index.duplicated()]
    NAT['Milk (pasteurized)'], gap = bridge(milk, ALL)
    NFLAG['Milk (pasteurized)'] = pd.Series(np.where(gap, 'Interpolated', np.where(ALL <= '2020-12-01', 'WFP Nairobi retail', 'Chain-linked WFP markets (UHT 2021-23, pasteurized 2024)')), index=ALL)
    OILI = ['Oil (vegetable)', 'Oil (vegetable, fortified)']
    o20 = wfp_median(w, OILI, 'Retail').reindex(pd.date_range('2006-01-01', '2020-12-01', freq='MS'))
    o = pd.concat([o20, chain(wfp_panel(w, OILI, 'Retail', '2020-10-01'), float(o20.loc['2020-10-01':].median()), pd.Timestamp('2020-12-01'), cpi).loc['2021-01-01':]])
    NAT['Vegetable oil'], gap = bridge(o, ALL)
    NFLAG['Vegetable oil'] = pd.Series(np.where(gap, 'Interpolated', np.where(ALL <= '2020-12-01', 'WFP retail, median of markets', 'Chain-linked WFP markets')), index=ALL)
    # beef and goat meat (WFP retail from Aug 2020): fixed-effects market index; before that, no domestic meat price history -> CPI back-cast
    for c, items in (('Beef', ['Meat (beef)']), ('Goat meat', ['Meat (goat)'])):
        pnl = wfp_panel(w, items, 'Retail', '2020-08-01'); a0 = pnl.index.min()
        s, gap = bridge(market_index(pnl), ALL)
        NAT[c] = growth_cast(s, cpi, 'back')
        NFLAG[c] = pd.Series(np.where(ALL < a0, 'Back-cast: CPI', np.where(gap, 'Interpolated', 'WFP markets, fixed-effects index')), index=ALL)
    # fish: WFP dried omena, wholesale, Jan-Aug 2021 only -> CPI both ways
    fish = wfp_median(w, ['Fish (omena, dry)'], 'Wholesale').reindex(ALL)
    s, gap = bridge(fish, ALL)
    s = growth_cast(growth_cast(s, cpi, 'back'), cpi, 'fwd')
    NAT['Fish (omena, dried)'] = s
    NFLAG['Fish (omena, dried)'] = pd.Series(np.where(fish.notna(), 'WFP wholesale, median of markets', 'Proxy: CPI-indexed from 2021 WFP prices'), index=ALL)
    NAT = pd.DataFrame(NAT)[[c for c, *_ in COMMODITIES]]; NFLAG = pd.DataFrame(NFLAG)[NAT.columns]
    assert NAT.notna().all().all(), NAT.isna().sum()[NAT.isna().sum() > 0]
    return NAT, NFLAG, SCALE

