# 5. COUNTY DISAGGREGATION
# =====================================================================================================================
GROUPS = {   # group: reference price, WFP items, price types, bulletin crop, member commodities
    'maize': dict(items=['Maize', 'Maize (white)', 'Maize (white, dry)'], types=('Wholesale', 'Retail'), bul='Maize', members=['Dry Maize']),
    'sorghum': dict(items=['Sorghum', 'Sorghum (red)', 'Sorghum (white)'], types=('Wholesale', 'Retail'), bul='Sorghum', members=['Sorghum']),
    'beans': dict(items=['Beans', 'Beans (dry)', 'Beans (kidney)', 'Beans (yellow)', 'Beans (rosecoco)', 'Beans (dolichos)'], types=('Wholesale', 'Retail'), bul='Beans', members=BEANS5),
    'potatoes': dict(items=['Potatoes (Irish)', 'Potatoes (Irish, red)', 'Potatoes (Irish, white)'], types=('Wholesale', 'Retail'), bul=None, members=POT2),
    'wheat': dict(items=[], types=('Wholesale',), bul='Wheat', members=['Wheat']),
    'wheat flour': dict(items=['Wheat flour'], types=('Retail',), bul=None, members=['Wheat flour']),
    'beef': dict(items=['Meat (beef)'], types=('Retail',), bul=None, members=['Beef']),
    'goat meat': dict(items=['Meat (goat)'], types=('Retail',), bul=None, members=['Goat meat']),
    'eggs': dict(items=[], types=('Wholesale',), bul=None, members=['Eggs']),
    'milk': dict(items=['Milk (cow, pasteurized)'], types=('Retail',), bul=None, members=['Milk (pasteurized)']),
    'fish': dict(items=['Fish (omena, dry)'], types=('Wholesale',), bul=None, members=['Fish (omena, dried)']),
    'oil': dict(items=['Oil (vegetable)', 'Oil (vegetable, fortified)'], types=('Retail',), bul=None, members=['Vegetable oil']),
}
VARIETY_ITEM = {'Beans (rosecoco)': 'Beans Rosecoco', 'Beans (dolichos)': 'Beans Dolichos (Njahi)', 'Beans (kidney)': 'Beans Canadian',
                'Potatoes (Irish, red)': 'Red Irish Potatoes', 'Potatoes (Irish, white)': 'White Irish Potatoes'}
MIN_DONORS = 6     # fewer counties with data than this -> use the county's average food price gap instead of neighbours

def county_model(w, NAT, bul_cty, counties):
    names = list(counties.county)
    DIST = {(a.county, b.county): km(a.center_lat, a.center_lon, b.center_lat, b.center_lon) for a in counties.itertuples() for b in counties.itertuples()}
    ref = {g: (np.exp(np.log(NAT[d['members']]).mean(axis=1)) if len(d['members']) > 1 else NAT[d['members'][0]]) for g, d in GROUPS.items()}
    item_group = {it: g for g, d in GROUPS.items() for it in d['items']}
    x = w[w.commodity.isin(item_group) & (w.month >= START) & (w.month <= END) & w.county.notna()].copy()
    x['group'] = x.commodity.map(item_group)
    x['ref'] = [ref[g][m] for g, m in zip(x.group, x.month)]
    x['ratio'] = x.p / x.ref
    bad = x[~x.ratio.between(0.25, 4)]
    for r in bad.itertuples(): log('WFP', r.commodity, f'{r.market} ({r.pricetype})', r.month, float(r.p), float(r.ref), 'Price >4x or <1/4 of national price', 'Removed')
    x = x[x.ratio.between(0.25, 4)]
    mk = x.groupby(['group', 'pricetype', 'county', 'market', 'month']).p.median().reset_index()
    obs = mk.groupby(['group', 'pricetype', 'county', 'month']).agg(p=('p', 'median'), n_markets=('market', 'nunique'),
                                                                    markets=('market', lambda s: ', '.join(sorted(set(s))))).reset_index()
    obs['ref'] = [ref[g][m] for g, m in zip(obs.group, obs.month)]
    obs['lr'] = np.log(obs.p / obs.ref)
    vobs = x[x.commodity.isin(VARIETY_ITEM)].assign(c9=lambda d: d.commodity.map(VARIETY_ITEM)).groupby(['c9', 'pricetype', 'county', 'month']).p.median()
    # retail markup where both price types exist in the same county and month
    MARKUP, PAIRS = {}, []
    for g in ('maize', 'sorghum', 'beans', 'potatoes'):
        a = obs[obs.group == g].pivot_table(index=['county', 'month'], columns='pricetype', values='p').dropna()
        MARKUP[g] = float((a.Retail / a.Wholesale).median())
        PAIRS += [(g, v) for v in (a.Retail / a.Wholesale)]
    # bulletin relative county prices (2025-26)
    BUL = {}
    for g, d in GROUPS.items():
        if d['bul']:
            b = bul_cty[(bul_cty.crop == d['bul']) & (bul_cty.level == 'Wholesale')].copy(); b['lp'] = np.log(b.kes_per_kg)
            BUL[g] = (b.lp - b.groupby('month').lp.transform('median')).groupby(b.county).median()
    def smooth(points):
        s = points.groupby(level=0).median().reindex(ALL)
        r = s.rolling(13, center=True, min_periods=1).median()
        return r.interpolate(limit_area='inside').ffill().bfill()
    LR, SRC = {}, {}
    for (g, t, c), s in obs.groupby(['group', 'pricetype', 'county']):
        LR[(g, t, c)] = smooth(s.set_index('month').lr); SRC[(g, t, c)] = f'own WFP {t.lower()}'
    LOO = []
    def idw(g, t, c, pool):
        near = sorted((DIST[(c, o)], o) for o in pool if o != c)[:3]
        wts = np.array([1 / max(dd, 10) ** 2 for dd, _ in near])
        return sum(wt * LR[(g, t, o)] for wt, (_, o) in zip(wts, near)) / wts.sum(), [o for _, o in near]
    order = ['maize', 'sorghum', 'beans', 'potatoes', 'wheat', 'wheat flour', 'beef', 'goat meat', 'milk', 'oil', 'fish', 'eggs']
    CAG = None
    for g in order:
        d = GROUPS[g]; mu = math.log(MARKUP[g]) if g in MARKUP else 0.0
        main_t = 'Wholesale' if 'Wholesale' in d['types'] else 'Retail'
        if 'Wholesale' in d['types'] and 'Retail' in d['types']:
            for c in names:
                if (g, 'Wholesale', c) not in LR and (g, 'Retail', c) in LR:
                    LR[(g, 'Wholesale', c)] = LR[(g, 'Retail', c)] - mu; SRC[(g, 'Wholesale', c)] = 'own WFP retail / markup'
        if g in BUL:
            own = {c: float(LR[(g, 'Wholesale', c)].loc['2019-01-01':].mean()) for c in names if (g, 'Wholesale', c) in LR}
            both = [c for c in own if c in BUL[g].index]
            kappa = float(np.median([own[c] - BUL[g][c] for c in both])) if len(both) >= 3 else 0.0
            for c in names:
                if (g, 'Wholesale', c) not in LR and c in BUL[g].index:
                    LR[(g, 'Wholesale', c)] = pd.Series(BUL[g][c] + kappa, index=ALL); SRC[(g, 'Wholesale', c)] = 'MoA county bulletin (2025-26 price gap)'
        donors = [c for c in names if (g, main_t, c) in LR]
        for c in [c for c in donors if SRC[(g, main_t, c)].startswith('own WFP')]:
            if len(donors) >= MIN_DONORS:
                est, _ = idw(g, main_t, c, donors); LOO.append((g, main_t, c, float(LR[(g, main_t, c)].mean()), float(est.mean())))
        for c in names:
            if (g, main_t, c) in LR: continue
            if len(donors) >= MIN_DONORS:
                est, nb = idw(g, main_t, c, donors); LR[(g, main_t, c)] = est; SRC[(g, main_t, c)] = 'neighbouring counties: ' + ', '.join(nb)
            else:
                LR[(g, main_t, c)] = CAG[c]; SRC[(g, main_t, c)] = 'county average food price gap'
        if 'Retail' in d['types'] and main_t == 'Wholesale':
            for c in names:
                if (g, 'Retail', c) not in LR:
                    LR[(g, 'Retail', c)] = LR[(g, 'Wholesale', c)] + mu; SRC[(g, 'Retail', c)] = 'county wholesale x markup (' + SRC[(g, 'Wholesale', c)] + ')'
        if g == 'wheat':   # after the staples: county average food price gap = median of the county's wholesale gaps
            CAG = {c: pd.concat([LR[(gg, 'Wholesale', c)] for gg in ('maize', 'sorghum', 'beans', 'potatoes', 'wheat')], axis=1).median(axis=1) for c in names}
    # long panel
    obs_i = obs.set_index(['group', 'pricetype', 'county', 'month'])
    recs = []
    for g, d in GROUPS.items():
        for t in d['types']:
            for c in names:
                lr, src = LR[(g, t, c)], SRC[(g, t, c)]
                kind = ('Estimated: own county trend' if src == f'own WFP {t.lower()}' else 'Estimated: own retail / markup' if src.startswith('own WFP retail')
                        else 'Estimated: own wholesale x markup' if src.startswith('county wholesale x markup (own') else 'Estimated: MoA county bulletin' if 'bulletin' in src
                        else 'Estimated: county average gap' if 'average' in src else 'Estimated: neighbouring counties')
                for comm in d['members']:
                    prem = NAT[comm] / ref[g]
                    est = NAT[comm] * np.exp(lr)
                    for m in ALL:
                        if (comm, t, c, m) in vobs.index: price, flag, n = float(vobs[(comm, t, c, m)]), 'Observed', None
                        elif (g, t, c, m) in obs_i.index:
                            o = obs_i.loc[(g, t, c, m)]; price = float(o.p * prem[m]); n = int(o.n_markets)
                            flag = 'Observed' if len(d['members']) == 1 else 'Observed (group price x variety premium)'
                        else: price, flag, n = float(est[m]), kind, None
                        recs.append((m, c, comm, t, price, flag, n))
    long = pd.DataFrame(recs, columns=['month', 'county', 'commodity', 'price_type', 'price_kes', 'flag', 'n_markets'])
    long['unit'] = long.commodity.map(UNIT_OF)
    ratios = pd.DataFrame([(g, t, c, s_, float(np.exp(LR[(g, t, c)].mean()))) for (g, t, c), s_ in SRC.items()],
                          columns=['commodity group', 'price type', 'county', 'ratio source', 'average ratio to national'])
    loo = pd.DataFrame(LOO, columns=['group', 'type', 'county', 'own', 'nbr']); loo['abs_pct_err'] = (np.exp(loo.nbr - loo.own) - 1).abs() * 100
    return long, obs, ratios, loo, MARKUP, pd.DataFrame(PAIRS, columns=['group', 'retail_to_wholesale'])

