def county_drivers(counties, w_markets, nat, EVC):
    idx = pd.MultiIndex.from_product([ALL, list(counties.county)], names=['month', 'county'])
    mm, cc = idx.get_level_values(0), idx.get_level_values(1)
    cl = pd.read_csv(F_CLIMATE, parse_dates=['month'])
    cl['county'] = cl.county_pcode.map(dict(zip(counties.pcode, counties.county)))
    W = cl.set_index(['month', 'county'])[['rain_1m_mm', 'rain_1m_pct', 'rain_3m_pct', 'ndvi', 'ndvi_pct']].reindex(idx)
    W.columns = ['Rainfall (mm)', 'Rainfall, % of normal', 'Rainfall last 3 months, % of normal', 'Vegetation (NDVI)', 'Vegetation, % of normal']
    S = pd.DataFrame(index=idx)
    S['Drought (3-month rain <75% of normal)'] = (W.iloc[:, 2] < 75).astype(int)
    S['Severe drought (<60%)'] = (W.iloc[:, 2] < 60).astype(int)
    S['Very wet month (>200% of normal and >50 mm)'] = ((W.iloc[:, 1] > 200) & (W.iloc[:, 0] > 50)).astype(int)
    S['Vegetation stress (<90% of normal)'] = (W.iloc[:, 4] < 90).astype(int)
    # access: hubs and markets (straight line; road = x1.3)
    mkts = w_markets.dropna(subset=['latitude', 'longitude'])
    rows = []
    for c in counties.itertuples():
        hubs = sorted((km(c.center_lat, c.center_lon, la, lo), h) for h, (la, lo) in HUBS.items())
        dm = sorted((km(c.center_lat, c.center_lon, m.latitude, m.longitude), m.market, m.admin2) for m in mkts.itertuples())
        other = next(x for x in dm if norm(x[2]) != norm(c.county))
        rows.append((c.county, hubs[0][1], hubs[0][0] * ROAD_FACTOR, hubs[1][1], hubs[1][0] * ROAD_FACTOR, dm[0][1], dm[0][0], other[1], other[0],
                     km(c.center_lat, c.center_lon, *HUBS['Nairobi']) * ROAD_FACTOR))
    acc = pd.DataFrame(rows, columns=['county', 'Nearest hub', 'Road km to nearest hub', 'Second hub', 'Road km to second hub', 'Nearest WFP market',
                                      'Km to nearest WFP market', 'Nearest market in another county', 'Km to alternate market (other county)', 'Road km to Nairobi']).set_index('county')
    A = acc.reindex(cc).set_index(idx).round(1)
    fr = nat['Freight rate (KES per tonne-km)'].reindex(mm).values
    A['Transport cost to nearest hub (KES/kg)'] = fr * A['Road km to nearest hub'].values / 1000
    A['Transport cost to second hub (KES/kg)'] = fr * A['Road km to second hub'].values / 1000
    EVT = {'Pest': 'Pest event', 'Crop disease': 'Crop disease event', 'Livestock disease': 'Livestock disease event', 'Policy': 'Policy event',
           'Political': 'Political shock (elections, unrest)', 'Global': 'Global shock', 'Climate': 'Climate emergency declared'}
    E = pd.DataFrame(0, index=idx, columns=list(EVT.values())); TXT = pd.Series('', index=idx)
    for s, e, typ, lab, cs, _ in EVC:
        msk = (mm >= pd.Timestamp(s + '-01')) & (mm <= pd.Timestamp(e + '-01')) & np.isin(cc, cs)
        E.loc[msk, EVT[typ]] = 1
        TXT[msk] = np.where(TXT[msk] == '', lab, TXT[msk] + '; ' + lab)
    SE = pd.concat([S, E], axis=1); SE['Shock count'] = SE.sum(axis=1); SE['Events in force'] = TXT.where(TXT != '', None)
    NCOLS = ['Murban crude (USD/bbl)', 'KES per USD', 'Diesel (KES/L)', 'Overall inflation, 12-month (%)', 'CPI index (Feb 2019=100, chained)', 'Food inflation (%)',
             'Fuel inflation (%)', 'Core inflation, non-food non-fuel (%)', 'Non-core inflation, food + fuel (%)', 'ONI (El Nino index)', 'ENSO phase',
             'Freight rate (KES per tonne-km)', 'Oil price jump (+20% in 3 months)', 'Shilling drop (-3% in 3 months)', 'High inflation (>10%)']
    N = pd.DataFrame({c + ' [national]': nat[c].reindex(mm).values for c in NCOLS}, index=idx)
    return W, A, SE, N, acc

# =====================================================================================================================
# 7. CHARTS
# =====================================================================================================================
BLUE, ORANGE, AQUA, RED, INK, INK2, GRID, SURF = '#2a78d6', '#eb6834', '#1baf7a', '#d03b3b', '#0b0b0b', '#52514e', '#e4e3df', '#fcfcfb'
SEQ = LinearSegmentedColormap.from_list('seq', ['#cde2fb', '#86b6ef', '#3987e5', '#1c5cab', '#0d366b'])
DIV = LinearSegmentedColormap.from_list('div', ['#1c5cab', '#86b6ef', '#f0efec', '#f19a92', '#c23434'])
plt.rcParams.update({'font.family': 'DejaVu Sans', 'font.size': 9, 'axes.edgecolor': GRID, 'axes.labelcolor': INK2, 'xtick.color': INK2, 'ytick.color': INK2,
                     'axes.titlecolor': INK, 'axes.titlesize': 10, 'axes.grid': True, 'grid.color': GRID, 'grid.linewidth': 0.6, 'axes.spines.top': False,
                     'axes.spines.right': False, 'figure.facecolor': SURF, 'axes.facecolor': SURF, 'savefig.facecolor': SURF, 'legend.frameon': False})

def make_charts(NAT, NFLAG, clean_daily, raw_daily, long, obs, pairs, ratios, counties, nat):
    figs = []
    # 1. national price indices with estimated periods shaded
    fig, axs = plt.subplots(5, 4, figsize=(13, 13), sharex=True)
    for ax, c in zip(axs.flat, NAT.columns):
        s = NAT[c] / NAT[c]['2019-01-01'] * 100
        est = NFLAG[c].str.startswith(('Back-cast', 'Proxy', 'Filled', 'Interpolated'))
        for t in s.index[est]: ax.axvspan(t, t + pd.DateOffset(months=1), color='#ecebe8', lw=0)
        ax.plot(s.index, s.values, color=BLUE, lw=1.6)
        ax.set_title(f'{c} ({UNIT_OF[c]})', loc='left'); ax.axhline(100, color=INK2, lw=0.6, ls=':')
    for ax in list(axs.flat)[len(NAT.columns):]: ax.axis('off')
    fig.suptitle('National reference prices, 2006-2024 (index, Jan 2019 = 100). Grey bands = filled, interpolated or back-cast months', x=0.01, ha='left', fontsize=12, color=INK)
    fig.tight_layout(rect=(0, 0, 1, 0.97)); figs.append(('1_national_price_index.png', fig))
    # 2. how much of each national series is real data, by year
    real = ~NFLAG.apply(lambda s: s.str.startswith(('Back-cast', 'Proxy', 'Filled', 'Interpolated')))
    share = real.groupby(real.index.year).mean().T * 100
    fig, ax = plt.subplots(figsize=(12, 6.5))
    im = ax.imshow(share.values, aspect='auto', cmap=SEQ, vmin=0, vmax=100)
    ax.set_yticks(range(len(share))); ax.set_yticklabels(share.index); ax.set_xticks(range(len(share.columns))); ax.set_xticklabels(share.columns, rotation=90)
    ax.grid(False); cb = fig.colorbar(im, ax=ax, shrink=0.8); cb.set_label('% of months with real (not estimated) national data')
    ax.set_title('Data coverage: share of months with real national price data, by commodity and year', loc='left')
    fig.tight_layout(); figs.append(('2_national_data_coverage.png', fig))
    # 3. county coverage over time
    cv = obs.assign(y=obs.month.dt.year).groupby(['y', 'pricetype']).county.nunique().unstack().reindex(range(2006, 2025)).fillna(0)
    fig, ax = plt.subplots(figsize=(10, 4.5))
    for t, col in (('Wholesale', BLUE), ('Retail', ORANGE)):
        ax.plot(cv.index, cv[t], color=col, lw=2, marker='o', ms=4); ax.text(cv.index[-1] + 0.2, cv[t].iloc[-1], t, color=INK2, va='center')
    ax.set_ylabel('counties with observed WFP prices'); ax.set_ylim(0, 47); ax.set_xlim(2006, 2025.8); ax.set_xticks(range(2006, 2025, 2))
    ax.set_title('Counties with real market prices each year (out of 47); all other county-months are estimated', loc='left')
    fig.tight_layout(); figs.append(('3_county_coverage.png', fig))
    # 4. outliers: counts and an example
    lg = pd.DataFrame(CLEAN_LOG, columns=['dataset', 'commodity', 'where', 'date', 'value', 'reference', 'rule', 'action'])
    used = set(NAT.columns) | {it for d in GROUPS.values() for it in d['items']}
    lg = lg[lg.commodity.isin(used) & (lg.rule != 'Price recorded as 0')]
    cnt = lg.groupby(['dataset', 'commodity']).size().sort_values(ascending=False).head(15)
    ex = lg[lg.dataset == 'MoA daily'].commodity.value_counts()
    exc = ex.index[0] if len(ex) else 'Dry Maize'
    fig, (a1, a2) = plt.subplots(1, 2, figsize=(14, 5), gridspec_kw={'width_ratios': [1, 1.6]})
    a1.barh([f'{d}: {c}' for d, c in cnt.index][::-1], cnt.values[::-1], color=BLUE, height=0.6)
    a1.set_title('Outliers removed, commodities in the panel', loc='left'); a1.set_xlabel('observations removed'); a1.grid(axis='y', visible=False); a1.xaxis.set_major_locator(MaxNLocator(integer=True))
    raw_r = raw_daily.rename(index={pd.Timestamp('2025-02-03'): pd.Timestamp('2025-01-31')})
    s_raw = raw_r[exc].replace(0, np.nan); s_cl = clean_daily[exc]
    rem = s_raw[s_raw.notna() & ~s_raw.index.isin(s_cl.dropna().index)]
    daily = s_cl.dropna().resample('D').mean()            # daily grid so the line breaks where there was no trading
    a2.plot(daily.index, daily.values, color=BLUE, lw=1, label='kept')
    a2.scatter(rem.index, rem.values, color=RED, s=22, zorder=3, label='removed outlier')
    a2.set_title(f'Example: {exc}, MoA daily prices (KES per {UNIT_OF.get(exc, "KES/kg").split("/")[1]})', loc='left'); a2.legend(loc='upper left')
    fig.tight_layout(); figs.append(('4_outliers.png', fig))
    # 5. retail markup distribution
    fig, ax = plt.subplots(figsize=(8, 4.5))
    gs = ['maize', 'beans', 'sorghum', 'potatoes']
    bp = ax.boxplot([pairs[pairs.group == g].retail_to_wholesale.values for g in gs], patch_artist=True, showfliers=False, widths=0.5)
    ax.set_xticks(range(1, len(gs) + 1)); ax.set_xticklabels(gs)
    for b in bp['boxes']: b.set(facecolor='#cde2fb', edgecolor=BLUE)
    for k_ in ('medians',): [l.set(color=INK, lw=1.5) for l in bp[k_]]
    ax.axhline(1, color=INK2, lw=0.8, ls=':'); ax.set_ylabel('retail price / wholesale price (same county, month)')
    ax.set_title('Retail markup over wholesale, where both are reported', loc='left')
    fig.tight_layout(); figs.append(('5_retail_markup.png', fig))
    # 6. county map: maize wholesale price relative to national
    geo = json.load(open(F_GEO))
    r = ratios[(ratios['commodity group'] == 'maize') & (ratios['price type'] == 'Wholesale')].set_index('county')
    own = set(obs[(obs.group == 'maize')].county)
    fig, ax = plt.subplots(figsize=(8, 9))
    norm_ = TwoSlopeNorm(vmin=0.6, vcenter=1.0, vmax=1.6)
    for f in geo['features']:
        name = f['properties']['county']; v = r['average ratio to national'].get(name, np.nan)
        polys = f['geometry']['coordinates'] if f['geometry']['type'] == 'MultiPolygon' else [f['geometry']['coordinates']]
        for poly in polys:
            ax.add_patch(MplPolygon(np.array(poly[0]), closed=True, facecolor=DIV(norm_(v)), edgecolor=INK if name in own else '#ffffff', lw=1.6 if name in own else 0.5))
    ax.autoscale(); ax.set_aspect('equal'); ax.axis('off')
    sm = plt.cm.ScalarMappable(cmap=DIV, norm=norm_); sm.set_array([]); cb = fig.colorbar(sm, ax=ax, shrink=0.6); cb.set_label('county maize wholesale price / national (average 2006-2024)')
    ax.set_title('Where maize is dearer or cheaper than the national price\n(dark outline = county has its own WFP market data)', loc='left')
    fig.tight_layout(); figs.append(('6_county_maize_price_map.png', fig))
    # 7. correlation of monthly price changes (2019-2024)
    ch = np.log(NAT.loc['2019-01-01':]).diff().dropna()
    cm = ch.corr()
    fig, ax = plt.subplots(figsize=(11, 9.5))
    im = ax.imshow(cm.values, cmap=DIV, vmin=-1, vmax=1)
    ax.set_xticks(range(len(cm))); ax.set_xticklabels(cm.columns, rotation=90); ax.set_yticks(range(len(cm))); ax.set_yticklabels(cm.index); ax.grid(False)
    for i in range(len(cm)):
        for j in range(len(cm)):
            if i != j and abs(cm.values[i, j]) >= 0.4: ax.text(j, i, f'{cm.values[i, j]:.1f}', ha='center', va='center', fontsize=7, color=INK)
    fig.colorbar(im, ax=ax, shrink=0.7).set_label('correlation of month-on-month price changes, 2019-2024')
    ax.set_title('Which prices move together (complements/substitutes); values shown where |r| >= 0.4', loc='left')
    fig.tight_layout(); figs.append(('7_price_change_correlation.png', fig))
    # 8. maize price and drought
    dr = nat['Drought (3-month rain <75% of normal)'].reindex(ALL)
    fig, ax = plt.subplots(figsize=(12, 4.5))
    for t in dr.index[dr == 1]: ax.axvspan(t, t + pd.DateOffset(months=1), color='#fde0cc', lw=0)
    ax.plot(ALL, NAT['Dry Maize'], color=BLUE, lw=1.8)
    ax.set_ylabel('KES per kg'); ax.set_title('National dry maize wholesale price; shaded = national 3-month rainfall below 75% of normal (drought)', loc='left')
    fig.tight_layout(); figs.append(('8_maize_price_and_drought.png', fig))
    paths = []
    for name, f in figs:
        p = FIG / name; f.savefig(p, dpi=130); plt.close(f); paths.append(p)
    return paths

# =====================================================================================================================
# 8. EXCEL
# =====================================================================================================================
FN = 'Arial'; GREEN = '1F5C4A'
f_title = Font(name=FN, size=14, bold=True, color=GREEN); f_sub = Font(name=FN, size=10, italic=True, color='555555')
f_head = Font(name=FN, size=10, bold=True, color='FFFFFF'); f_cat = Font(name=FN, size=9, bold=True, color=GREEN)
f_body = Font(name=FN, size=10); f_bold = Font(name=FN, size=10, bold=True)
fill_head = PatternFill('solid', fgColor=GREEN)
_thin = Side(style='thin', color='C9D6D0'); box = Border(top=_thin, bottom=_thin, left=_thin, right=_thin)
CATFILL = {'': 'FFFFFF', 'Cereals': 'E8F1EC', 'Legumes': 'FFF3D6', 'Roots & tubers': 'F6E7DA', 'Livestock, dairy & fish': 'EFEFEF', 'Other food': 'FCE4EC',
           'County weather': 'DCEFF7', 'Distance & transport': 'E3F1E7', 'County shocks': 'F8D7D3', 'Pest, disease & events': 'F8D7D3', 'National drivers': 'E1DCF0'}
FLAGFILL = {'Estimated: own county trend': 'FFF3C4', 'Estimated: own retail / markup': 'FFF3C4', 'Estimated: own wholesale x markup': 'FFF3C4',
            'Estimated: MoA county bulletin': 'FAD9C8', 'Estimated: neighbouring counties': 'F2B8A2', 'Estimated: county average gap': 'E6C3B5'}
NATFILL = {'Back-cast': 'E6C3B5', 'Proxy': 'E6C3B5', 'Filled': 'FAD9C8', 'Interpolated': 'FAD9C8', 'Thin': 'FFF3C4'}

def write_excel(PANEL, FLAGS, GH, NAT, NFLAG, moa_obs, moa_days, long, obs, ratios, loo, MARKUP, SCALE, acc, counties, EVC, chart_paths):
    wb = Workbook(); wb.remove(wb['Sheet'])
    def sheet(name, title, sub):
        ws = wb.create_sheet(name); ws['A1'] = title; ws['A1'].font = f_title; ws['A2'] = sub; ws['A2'].font = f_sub; ws.sheet_view.showGridLines = False; return ws
    def head(ws, r, c, v, wdt=None):
        x = ws.cell(row=r, column=c, value=v); x.font = f_head; x.fill = fill_head; x.border = box
        x.alignment = Alignment(wrap_text=True, vertical='center', horizontal='center')
        if wdt: ws.column_dimensions[L(c)].width = wdt
    def put(ws, r, c, v, fmt=None, bold=False, wrap=False, fill=None):
        if isinstance(v, float) and np.isnan(v): v = None
        if isinstance(v, np.integer): v = int(v)
        if isinstance(v, np.floating): v = None if np.isnan(v) else float(v)
        if isinstance(v, pd.Timestamp): v = v.to_pydatetime()
        x = ws.cell(row=r, column=c, value=v); x.font = f_bold if bold else f_body; x.border = box
        if fmt: x.number_format = fmt
        if wrap: x.alignment = Alignment(wrap_text=True, vertical='top')
        if fill: x.fill = PatternFill('solid', fgColor=fill)
        return x
    def table(ws, df, r0=4, widths=None, wrap=()):
        for j, h in enumerate(df.columns, start=1): head(ws, r0, j, h, (widths or {}).get(h, 14))
        for i, row in enumerate(df.itertuples(index=False)):
            for j, v in enumerate(row, start=1):
                fmt = 'mmm yyyy' if isinstance(v, (pd.Timestamp, datetime.datetime)) else ('0.00' if isinstance(v, (float, np.floating)) else None)
                put(ws, r0 + 1 + i, j, v, fmt, wrap=df.columns[j - 1] in wrap)
        ws.freeze_panes = ws.cell(row=r0 + 1, column=2)
        if len(df): ws.auto_filter.ref = f'A{r0}:{L(len(df.columns))}{r0 + len(df)}'
    # README
    rd = wb.create_sheet('README'); rd.sheet_view.showGridLines = False
    rd.column_dimensions['A'].width = 28; rd.column_dimensions['B'].width = 120
    rd['A1'] = 'SokoRadar county food price panel, Jan 2006 - Dec 2024'; rd['A1'].font = f_title
    rd['A2'] = 'Built by sokoradar_pipeline.py from the files in raw/. Rerun the script to rebuild everything (prices, cleaning log, charts, this workbook).'; rd['A2'].font = f_sub
    real = (long.flag.str.startswith('Observed')).mean() * 100
    ROWS = [
        ('County_Panel', f'Main table: one row per county and month (47 x 228 = {len(PANEL):,} rows). {len(FLAGS.columns)} price columns (wholesale and retail, KES), county weather, distance and transport, shocks and events, national drivers. Cell colour shows how the price was obtained.'),
        ('Price_Flags', 'Same rows: the method behind each price cell (Observed, own county trend, markup, MoA bulletin, neighbouring counties, county average gap).'),
        ('National_Prices', 'One national reference price per commodity and month, with how each month was obtained (MoA observed / thin / filled; WFP; chain-linked; back-cast).'),
        ('MoA_Monthly_Raw', 'MoA daily prices after outlier removal, averaged by month, before any filling, with the number of trading days.'),
        ('Cleaning_Log', 'Every price removed as an outlier or zero, with the rule that removed it.'),
        ('Missing_Report', 'How many months / county-months were real data vs filled or estimated, by commodity.'),
        ('Observed_WFP', 'All real county prices from WFP markets (county median across markets).'),
        ('County_Ratios', 'Each county’s price relative to the national price, where the ratio came from, and an accuracy check.'),
        ('Counties, Events_County', 'County reference data (location, ASAL class, nearest hubs and markets); dated events and the counties they apply to.'),
        ('Charts', 'Charts to understand the data (also saved as PNG in output/figures).'),
        ('Real vs estimated', f'Only {real:.1f}% of county prices are real WFP observations; the rest are estimates. Use Price_Flags to filter, or weight models by data quality.'),
        ('Colour key (prices)', 'White = observed. Yellow = estimated from the county’s own data. Light orange = MoA county bulletin. Orange = 3 nearest counties. Brown = county average food price gap (eggs, fish).'),
    ]
    for i, (a, b) in enumerate(ROWS):
        put(rd, 4 + i, 1, a, bold=True, wrap=True); put(rd, 4 + i, 2, b, wrap=True); rd.row_dimensions[4 + i].height = 34
    r0 = 4 + len(ROWS) + 1
    put(rd, r0, 1, 'Method', bold=True)
    STEPS = [
        ('1. Raw data', 'MoA daily prices (Jan 2019 - Jan 2025) and MoA bulletin (county prices 2025-26); WFP market prices (2006 onward, 280 markets); IMF world prices; CHIRPS rainfall and MODIS vegetation by county; national drivers (CBK, KNBS, EIA, NOAA).'),
        ('2. Outliers', 'MoA daily: zero prices removed; prices >3x or <1/3 of the 21-day rolling median removed. WFP: prices >3x or <1/3 of the same market’s rolling median (5 reports) removed; county prices >4x or <1/4 of the national price removed.'),
        ('3. Missing values', 'MoA monthly = average of trading days (10+ days Observed; 1-9 Thin). Months with no trading: MoA bulletin trend (maize, beans, potatoes) or average seasonal growth for that calendar month, nudged to meet the next real price. 2006-2018: WFP wholesale (6 main markets) scaled to the MoA level.'),
        ('4. New items', 'Wheat and eggs: MoA from 2019; back-cast with world wheat price in KES (to Jun 2017, then CPI) and CPI. MoA wheat stops in Jan 2024 and is carried to Dec 2024 with the WFP wheat flour trend. Wheat flour, beef, goat meat: WFP retail from Dec 2018 / Aug 2020, combined across changing markets with a fixed-effects index (market level + month level); back-cast with the wheat grain price (flour) and CPI (meat). Fish: WFP dried omena Jan-Aug 2021 only; all other months CPI-indexed (proxy - use with care).'),
        ('5. Counties', f'County price = national price x county ratio. Ratio: own WFP prices -> MoA county bulletin -> 3 nearest counties -> county average food price gap. Retail = wholesale x markup (maize {MARKUP["maize"]:.2f}, beans {MARKUP["beans"]:.2f}, sorghum {MARKUP["sorghum"]:.2f}, potatoes {MARKUP["potatoes"]:.2f}).'),
        ('6. Accuracy', 'Counties with their own data re-estimated from neighbours only: median error of the county price level ' + ', '.join(f'{g} {v:.0f}%' for (g, _), v in loo.groupby(['group', 'type']).abs_pct_err.median().items()) + '.'),
    ]
    for i, (a, b) in enumerate(STEPS):
        put(rd, r0 + 1 + i, 1, a, bold=True, wrap=True); put(rd, r0 + 1 + i, 2, b, wrap=True); rd.row_dimensions[r0 + 1 + i].height = 48
    # County_Panel
    ws = sheet('County_Panel', 'County food prices (KES) and drivers, Jan 2006 - Dec 2024, wholesale and retail, 47 counties',
               'Prices: white = observed (WFP markets in the county); yellow = from the county’s own WFP data; light orange = MoA county bulletin; orange = 3 nearest counties; brown = county average food price gap. Method per cell in Price_Flags.')
    for j, (cat, h) in enumerate(GH, start=1):
        a = ws.cell(row=3, column=j, value=cat or None); a.font = f_cat; a.fill = PatternFill('solid', fgColor=CATFILL[cat]); a.border = box
        head(ws, 4, j, h, 11 if j == 1 else 13 if h in ('County', 'Former province', 'ASAL class') else 40 if h == 'Events in force' else 12)
    ws.row_dimensions[4].height = 72
    cols = list(PANEL.columns); pset = set(FLAGS.columns)
    textc = {'County', 'Former province', 'ASAL class', 'Nearest hub', 'Second hub', 'Nearest WFP market', 'Nearest market in another county', 'Events in force', 'ENSO phase [national]'}
    flagc = {c for c in cols if c not in textc and c not in ('Month', 'County code', 'Shock count') and PANEL[c].dropna().isin([0, 1]).all()}
    fmt = {c: 'mmm yyyy' if c == 'Month' else None if (c in textc or c in flagc or c in ('County code', 'Shock count')) else '0.00' for c in cols}
    fills = {k_: PatternFill('solid', fgColor=v) for k_, v in FLAGFILL.items()}
    V = PANEL.values; FV = FLAGS.values; fpos = {c: FLAGS.columns.get_loc(c) for c in FLAGS.columns}
    for i in range(len(PANEL)):
        for j, c in enumerate(cols):
            x = put(ws, 5 + i, j + 1, V[i, j], fmt[c])
            if c in pset and FV[i, fpos[c]] in fills: x.fill = fills[FV[i, fpos[c]]]
    last = 4 + len(PANEL)
    for c in flagc:
        j = cols.index(c) + 1
        ws.conditional_formatting.add(f'{L(j)}5:{L(j)}{last}', CellIsRule(operator='equal', formula=['1'], fill=PatternFill('solid', fgColor='F8D7D3')))
    ws.freeze_panes = 'D5'; ws.auto_filter.ref = f'A4:{L(len(cols))}{last}'
    # Price_Flags
    fs = sheet('Price_Flags', 'How each county price was obtained', 'Same rows as County_Panel.')
    F2 = pd.concat([PANEL[['Month', 'County code', 'County']].reset_index(drop=True), FLAGS.reset_index(drop=True).replace({'Estimated: ': ''}, regex=True)], axis=1)
    F2.columns = [c.split(' (KES')[0] for c in F2.columns]
    table(fs, F2, widths={**{c: 17 for c in F2.columns}, 'Month': 11, 'County code': 8, 'County': 14}); fs.freeze_panes = 'D5'
    # National_Prices
    ns = sheet('National_Prices', 'National reference prices (KES), 2006 - 2024, and how each month was obtained',
               'Shaded: light yellow = thin month (1-9 trading days); light orange = filled or interpolated; brown = back-cast / proxy. Method columns to the right.')
    head(ns, 4, 1, 'Month', 11)
    for j, c in enumerate(NAT.columns, start=2):
        a = ns.cell(row=3, column=j, value=CAT_OF[c]); a.font = f_cat; a.fill = PatternFill('solid', fgColor=CATFILL[CAT_OF[c]]); a.border = box
        head(ns, 4, j, f'{c} ({UNIT_OF[c]})', 12)
    j0 = len(NAT.columns) + 3
    for j, c in enumerate(NAT.columns): head(ns, 4, j0 + j, f'{c}: method', 24)
    ns.row_dimensions[4].height = 58
    for i, m in enumerate(ALL):
        put(ns, 5 + i, 1, m, 'mmm yyyy')
        for j, c in enumerate(NAT.columns):
            fl = NFLAG.loc[m, c]; fc = next((v for k_, v in NATFILL.items() if fl.startswith(k_)), None)
            put(ns, 5 + i, 2 + j, NAT.loc[m, c], '0.00', fill=fc); put(ns, 5 + i, j0 + j, fl)
    ns.freeze_panes = 'B5'
    # MoA monthly raw
    mr = sheet('MoA_Monthly_Raw', 'MoA prices after outlier removal: monthly average (KES) and trading days, before filling', 'Blank = no trading days that month (filled later).')
    mo = moa_obs[[c for c in moa_obs.columns if c in NAT.columns]]
    head(mr, 4, 1, 'Month', 11)
    for j, c in enumerate(mo.columns): head(mr, 4, 2 + j, f'{c} (KES/{"tray" if c == "Eggs" else "kg"})', 12); head(mr, 4, 3 + len(mo.columns) + j, f'{c}: trading days', 12)
    for i, m in enumerate(mo.index):
        put(mr, 5 + i, 1, m, 'mmm yyyy')
        for j, c in enumerate(mo.columns):
            put(mr, 5 + i, 2 + j, mo.loc[m, c], '0.00'); put(mr, 5 + i, 3 + len(mo.columns) + j, int(moa_days.loc[m, c]))
    mr.freeze_panes = 'B5'
    # Cleaning log
    cl = pd.DataFrame(CLEAN_LOG, columns=['dataset', 'commodity', 'market / series', 'date', 'value removed', 'reference (median or national)', 'rule', 'action'])
    cs = sheet('Cleaning_Log', 'Outliers and zero prices removed', f'{len(cl):,} observations removed. Rules in README.')
    table(cs, cl.sort_values(['dataset', 'commodity', 'date']), widths={'commodity': 22, 'market / series': 30, 'rule': 34, 'date': 12})
    for r in range(5, 5 + len(cl)): cs.cell(row=r, column=4).number_format = 'dd mmm yyyy'
    # Missing report
    ms = sheet('Missing_Report', 'Real vs filled data', 'Top: national series, months by method. Bottom: county prices, share of county-months by method.')
    nm = NFLAG.apply(lambda s: s.value_counts()).fillna(0).astype(int).T
    nm.insert(0, 'commodity', nm.index)
    table(ms, nm, widths={'commodity': 22, **{c: 14 for c in nm.columns[1:]}})
    ms.row_dimensions[4].height = 60
    cm_ = long.assign(col=long.commodity + ' ' + long.price_type.str.lower()).groupby(['col', 'flag']).size().unstack().fillna(0)
    cm_ = (cm_.div(cm_.sum(axis=1), axis=0) * 100).round(1)
    r1 = 6 + len(nm) + 2
    put(ms, r1 - 1, 1, 'County prices: % of county-months by method', bold=True)
    head(ms, r1, 1, 'commodity, price type', 26)
    for j, c in enumerate(cm_.columns, start=2): head(ms, r1, j, c, 16)
    ms.row_dimensions[r1].height = 60
    for i, (ix, row) in enumerate(cm_.iterrows()):
        put(ms, r1 + 1 + i, 1, ix)
        for j, v in enumerate(row, start=2): put(ms, r1 + 1 + i, j, v, '0.0')
    # Observed_WFP
    ob = obs.assign(ratio_to_national=np.exp(obs.lr)).drop(columns='lr')[['month', 'county', 'group', 'pricetype', 'p', 'n_markets', 'markets', 'ref', 'ratio_to_national']]
    ob.columns = ['month', 'county', 'commodity group', 'price type', 'price (KES per unit)', 'markets (n)', 'markets', 'national reference price', 'ratio to national']
    os_ = sheet('Observed_WFP', 'Real county prices from WFP markets, 2006 - 2024', 'Median across WFP markets in the county; bags converted to per kg, 500 ml to per litre.')
    table(os_, ob.sort_values(['commodity group', 'price type', 'county', 'month']), widths={'county': 14, 'markets': 30})
    # County ratios + accuracy
    rs = sheet('County_Ratios', 'County price relative to national, and where it comes from', 'Accuracy check to the right.')
    table(rs, ratios.sort_values(['commodity group', 'price type', 'county']), widths={'ratio source': 60, 'county': 14}, wrap=('ratio source',))
    lo = loo.groupby(['group', 'type']).abs_pct_err.agg(['count', 'median', 'mean']).round(1).reset_index()
    lo.columns = ['commodity group', 'price type', 'counties tested', 'median abs error (%)', 'mean abs error (%)']
    c0 = len(ratios.columns) + 2
    rs.cell(row=3, column=c0, value='Each county with its own WFP data re-estimated from its 3 nearest counties only').font = f_bold
    for j, h in enumerate(lo.columns): head(rs, 4, c0 + j, h, 15)
    for i, row in enumerate(lo.itertuples(index=False)):
        for j, v in enumerate(row): put(rs, 5 + i, c0 + j, v)
    # Counties and events
    ct = sheet('Counties', 'Counties: location, ASAL class, hubs and markets', 'Road km = straight-line km x 1.3.')
    table(ct, counties.merge(acc.reset_index(), on='county'), widths={'county': 14, 'Nearest WFP market': 22, 'Nearest market in another county': 22})
    ev = pd.DataFrame([(s, e, t, lab, len(c), 'All 47 counties' if len(c) == 47 else ', '.join(sorted(c)), src) for s, e, t, lab, c, src in EVC],
                      columns=['start', 'end', 'type', 'event', 'counties (n)', 'counties', 'source'])
    es = sheet('Events_County', 'Events and the counties they apply to', '')
    table(es, ev, widths={'event': 40, 'counties': 70, 'source': 36, 'type': 16}, wrap=('counties', 'event', 'source'))
    # Charts
    ch = sheet('Charts', 'Charts', 'Also saved as PNG files in output/figures.')
    r = 4
    for p in chart_paths:
        img = XLImage(str(p)); scale = 900 / img.width; img.width, img.height = int(img.width * scale), int(img.height * scale)
        ch.add_image(img, f'A{r}'); r += int(img.height / 20) + 3
    wb._sheets = [wb[s] for s in ['README', 'County_Panel', 'Price_Flags', 'National_Prices', 'MoA_Monthly_Raw', 'Cleaning_Log', 'Missing_Report',
                                  'Observed_WFP', 'County_Ratios', 'Counties', 'Events_County', 'Charts']]
    for w_ in wb.worksheets: w_.sheet_properties.tabColor = 'D9480F' if w_.title == 'County_Panel' else GREEN if w_.title == 'README' else 'B7C9C1'
    wb.active = 1
    wb.save(OUT_XLSX)

# =====================================================================================================================
# MAIN
# =====================================================================================================================
def step(msg):
    print(f'[{datetime.datetime.now():%H:%M:%S}] {msg}', flush=True)

def main():
    CLEAN_LOG.clear()
    setup_paths()
    step('1/8 Loading counties, national drivers and MoA daily prices')
    counties, cmap = load_counties()
    nat = pd.read_csv(F_NATIONAL); nat.index = pd.to_datetime(nat.Month + '-01'); nat = nat.drop(columns='Month').reindex(ALL)
    # 1-3: MoA
    raw_daily, meta = load_moa_daily(F_MOA_DAILY)
    cat_of = dict(zip(meta.commodity, meta.category))
    step('2/8 Cleaning outliers in MoA daily prices; reading the MoA bulletin')
    clean_daily = clean_moa_daily(raw_daily)
    bul_nat, bul_cty = load_bulletin(F_MOA_BULLETIN, cmap)
    step('3/8 Monthly MoA prices and filling missing months')
    moa_obs, moa_days, filled, flag2 = moa_monthly(clean_daily, cat_of, bul_nat)
    moa_flag = pd.DataFrame(np.where(moa_days >= 10, 'Observed', ''), index=moa_days.index, columns=moa_days.columns)
    print(f'MoA: {raw_daily.shape[0]} days x {raw_daily.shape[1]} commodities; removed {sum(1 for r in CLEAN_LOG if r[0] == "MoA daily")} values')
    step('4/8 Loading and cleaning WFP market prices')
    w = clean_wfp(load_wfp(cmap))
    print(f'WFP: {len(w):,} prices after cleaning; removed {sum(1 for r in CLEAN_LOG if r[0] == "WFP")}')
    step('5/8 Building national price series 2006-2024')
    NAT, NFLAG, SCALE = national_series(w, filled, flag2, moa_flag, nat)
    step('6/8 County prices (observed + estimated), wholesale and retail')
    long, obs, ratios, loo, MARKUP, pairs = county_model(w, NAT, bul_cty, counties)
    print('markups', {k: round(v, 2) for k, v in MARKUP.items()})
    print('accuracy (median abs % error, neighbours vs own data):', loo.groupby(['group', 'type']).abs_pct_err.median().round(1).to_dict())
    step('7/8 County drivers: weather, distance, transport, events')
    EVC = county_events(counties)
    W, A, SE, N, acc = county_drivers(counties, pd.read_csv(F_WFP_MARKETS), nat, EVC)
    long['col'] = long.commodity + ' ' + long.price_type.str.lower() + ' (' + long.unit + ')'
    pcols = [f'{c} {t.lower()} ({u})' for c, _, u, ts in COMMODITIES for t in ts]
    PW = long.pivot_table(index=['month', 'county'], columns='col', values='price_kes', aggfunc='first')[pcols]
    FW = long.pivot_table(index=['month', 'county'], columns='col', values='flag', aggfunc='first')[pcols]
    idx = W.index; PW, FW = PW.reindex(idx), FW.reindex(idx)
    ci = counties.set_index('county')
    K = pd.DataFrame({'Month': idx.get_level_values(0), 'County code': ci.code.reindex(idx.get_level_values(1)).values, 'County': idx.get_level_values(1),
                      'Former province': ci.former_province.reindex(idx.get_level_values(1)).values, 'ASAL class': ci.asal.reindex(idx.get_level_values(1)).values}, index=idx)
    PANEL = pd.concat([K, PW, W, A, SE, N], axis=1)
    PANEL = PANEL.sort_values(['County code', 'Month']); FLAGS = FW.loc[PANEL.index]
    EVC_COLS = ['Pest event', 'Crop disease event', 'Livestock disease event', 'Policy event', 'Political shock (elections, unrest)', 'Global shock', 'Climate emergency declared']
    GH = ([('', c) for c in K.columns] + [(CAT_OF[c.split(' wholesale')[0].split(' retail')[0]], c) for c in PW.columns] + [('County weather', c) for c in W.columns]
          + [('Distance & transport', c) for c in A.columns] + [('Pest, disease & events' if c in EVC_COLS or c == 'Events in force' else 'County shocks', c) for c in SE.columns]
          + [('National drivers', c) for c in N.columns])
    assert PW.notna().all().all() and [h for _, h in GH] == list(PANEL.columns)
    step('8/8 Charts and Excel workbook (about a minute)')
    try:
        paths = make_charts(NAT, NFLAG, clean_daily, raw_daily, long, obs, pairs, ratios, counties, nat)
    except Exception as e:                       # charts are optional: never lose the data because of a plotting problem
        print('  Charts skipped because of an error:', repr(e)); paths = []
    try:
        write_excel(PANEL, FLAGS, GH, NAT, NFLAG, moa_obs, moa_days, long, obs, ratios, loo, MARKUP, SCALE, acc, counties, EVC, paths)
    except PermissionError:
        sys.exit(f'Cannot save {OUT_XLSX} - close the file in Excel and run again.')
    lg = long.merge(counties[['county', 'code']], on='county').rename(columns={'code': 'county_code'})
    lg = lg[['month', 'county_code', 'county', 'commodity', 'price_type', 'unit', 'price_kes', 'flag', 'n_markets']].sort_values(['county_code', 'commodity', 'price_type', 'month'])
    lg.assign(month=lg.month.dt.strftime('%Y-%m'), price_kes=lg.price_kes.round(2)).to_csv(OUT / 'SokoRadar_County_2006_2024_long.csv', index=False)
    NAT.assign(Month=NAT.index.strftime('%Y-%m')).set_index('Month').round(3).to_csv(OUT / 'national_prices_2006_2024.csv')
    print(f'Saved {OUT_XLSX.name}: {PANEL.shape[0]:,} county-months x {PANEL.shape[1]} columns; {len(paths)} charts; real share {long.flag.str.startswith("Observed").mean():.1%}')
    return dict(NAT=NAT, NFLAG=NFLAG, long=long, obs=obs, ratios=ratios, loo=loo, PANEL=PANEL, FLAGS=FLAGS, SCALE=SCALE, MARKUP=MARKUP)

def run():
    print(f'SokoRadar pipeline | Python {sys.version.split()[0]} | pandas {pd.__version__} | numpy {np.__version__} | matplotlib {matplotlib.__version__} | openpyxl {openpyxl.__version__}')
    try:
        return main()
    except SystemExit:
        raise
    except Exception:
        traceback.print_exc()
        print('\nThe pipeline stopped with the error above. Please send the full message (and the version line at the top) to the team.')

